//! Compliance catalog: control tags → OSCAL controls → candidate operations.
//!
//! Table is `oscal/TAG-TAXONOMY.md` as code; `oscal/catalogs/etched-catalog`
//! is authoritative for controls and the sealed blobs (`opblob inspect`)
//! for method names and capabilities. Qualifier tags (`action:*`,
//! `approval:*`, `surface:*`, `data:*`, `model:*`) never match controls —
//! they steer the decision.

use crate::model::Operation;

/// One taxonomy row: tag, control, and candidate `(plugin, method,
/// sealed capability)` triples. Capability is `None` when no blob is
/// sealed for the method yet (e.g. `web3` anchor: drafts only).
/// `(plugin, sealed method, sealed capability or None if unsealed)`.
type SealedOp = (&'static str, &'static str, Option<&'static str>);
/// `(control tag, OSCAL control, candidate sealed operations)`.
type TaxonomyRow = (&'static str, &'static str, &'static [SealedOp]);
const TAXONOMY: &[TaxonomyRow] = &[
    (
        "pii",
        "etched-pt-1",
        &[(
            "schema_tag_registry",
            "get_policy",
            Some("cap.governance.schema-tag-registry.read@v1"),
        )],
    ),
    (
        "access-control",
        "etched-ac-1",
        &[
            ("elevation", "authorize_task", Some("elevation.authorize")),
            (
                "schema_tag_registry",
                "get_tag",
                Some("cap.governance.schema-tag-registry.read@v1"),
            ),
        ],
    ),
    (
        "audit",
        "etched-au-1",
        &[
            (
                "identity_sled",
                "get_own_identity",
                Some("cap.identity.sled.self.read@v1"),
            ),
            (
                "routing_decision",
                "get_decision",
                Some("cap.governance.routing-decision.read@v1"),
            ),
            (
                "routing_decision",
                "list_decisions",
                Some("cap.governance.routing-decision.read@v1"),
            ),
        ],
    ),
    (
        "retention",
        "etched-si-1",
…
    ),
…
];

import type { Spec } from "@json-render/core";

/**
 * Adapted from the dashboard ChatOnly flat-map spec. The direct component
 * names are preserved; chatThread reads the selected door-resolved scope.
 * Adapter-specific status copy lives in components that read ChatAdapter.
 */
export const antigravitySpec: Spec = {
  root: "root",
  elements: {
    root: {
      type: "container",
      props: { className: "chat-only-layout" },
      children: ["chat-header", "workspace-navigation", "chat-mode", "tched-picker", "antigravity-chat"],
    },
    "chat-header": {
      type: "pageHeader",
      props: {
        title: "3tched Chat",
        subtitle: "One door · one credential · scoped conversation and UI",
      },
    },
    "chat-mode": {
      type: "chatModeSelector",
      props: {},
    },
    "workspace-navigation": {
      type: "workbenchNavigation",
      props: {},
    },
    "tched-picker": {
      type: "tchedRouterPicker",
      props: { className: null },
    },
    "antigravity-chat": {
      type: "antigravityChatContainer",
      props: {
        streamId: "stream_antigravity_01",
        title: null,
        mode: "live",
        workspace: true,
        active: null,
        open: null,
        placeholder: "Ask a question or describe what to show",
      },
      children: ["chat-thread"],
    },
    "chat-thread": {
      type: "chatThread",
      props: { streamId: "stream_antigravity_01" },
    },
  },
};

