                .iter()
                .find(|c| {
                    c["props"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .any(|p| p["name"] == "tag" && p["value"] == tag)
                })
                .unwrap();
            let sealed: Vec<(String, String, Option<String>)> = {
                let raw_ops = control["props"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .find(|p| p["name"] == "sealed-operations")
                    .unwrap()["value"]
                    .as_str()
